const {plotX, plotY, plotW, plotH, axisMax, tickStep, values, xLabels, yTitle, xTitle, barColor} = cfg;
let s = '';
// axes
s += `<line x1="${plotX}" y1="${plotY}" x2="${plotX}" y2="${plotY+plotH}" stroke="#999" stroke-width="1"/>`;
s += `<line x1="${plotX}" y1="${plotY+plotH}" x2="${plotX+plotW}" y2="${plotY+plotH}" stroke="#999" stroke-width="1"/>`;
// grid and ticks
for (let v=0; v<=axisMax; v+=tickStep) {
  const y = plotY + plotH - (v/axisMax)*plotH;
  s += `<line x1="${plotX}" y1="${y}" x2="${plotX+plotW}" y2="${y}" stroke="#ccc" stroke-width="1"/>`;
  s += `<text x="${plotX-6}" y="${y+6}" font-size="18" fill="#333" text-anchor="end">${v}</text>`;
}
// bars
const n = values.length;
const groupW = plotW / n;
const barWidth = Math.min(cfg.barWidth || 80, groupW*0.6);
values.forEach((val,i)=>{
  const x = plotX + i*groupW + (groupW-barWidth)/2;
  const h = (val/axisMax)*plotH;
  const y = plotY + plotH - h;
  s += `<rect x="${x}" y="${y}" width="${barWidth}" height="${h}" fill="${barColor || '#4a90e2'}"/>`;
  s += `<text x="${x+barWidth/2}" y="${y-8}" font-size="18" fill="#111" text-anchor="middle">${val}</text>`;
  s += `<text x="${plotX + i*groupW + groupW/2}" y="${plotY+plotH+20}" font-size="18" fill="#333" text-anchor="middle">${xLabels[i]}</text>`;
});
// titles
s += `<text x="20" y="${plotY+plotH/2}" transform="rotate(-90 20 ${plotY+plotH/2})" font-size="18" fill="#333">${yTitle}</text>`;
s += `<text x="${plotX+plotW/2}" y="${plotY+plotH+40}" font-size="18" fill="#333" text-anchor="middle">${xTitle}</text>`;
svg.innerHTML = s;
```
