  s += `<text x="${x}" y="${plotY+plotH+30}" font-size="18" fill="#333" text-anchor="middle">${v}</text>`;
}
// bars
const barHeight = cfg.barHeight || 52;
const barGap = cfg.barGap || 70;
values.forEach((val,i)=>{
  const y = plotY + i*(barHeight+barGap);
  const w = (val/axisMax)*plotW;
  const color = (cfg.barColors && cfg.barColors[i]) || '#4a90e2';
  s += `<text x="${plotX-10}" y="${y+barHeight/2+6}" font-size="20" fill="#111" text-anchor="end">${rowLabels[i]}</text>`;
  s += `<rect x="${plotX}" y="${y}" width="${w}" height="${barHeight}" fill="${color}"/>`;
  s += `<text x="${plotX+w+10}" y="${y+barHeight/2+6}" font-size="20" fill="#111">${val}% (${cfg.counts[i]})</text>`;
});
// x title
s += `<text x="${plotX+plotW/2}" y="${plotY+plotH+60}" font-size="18" fill="#333" text-anchor="middle">${xTitle}</text>`;
