        var color = (cfg.barColors && cfg.barColors[i]) || '#4a90e2';
        s += '<text x="'+(plotX-10)+'" y="'+(y+barHeight/2+6)+'" font-size="20" fill="#111" text-anchor="end">'+cfg.rowLabels[i]+'</text>';
