      }
      s += '<text x="'+(plotX+plotW/2)+'" y="'+(plotY+plotH+60)+'" font-size="18" fill="#333" text-anchor="middle">'+cfg.xTitle+'</text>';
    } else {
      var plotX=cfg.plotX, plotY=cfg.plotY, plotW=cfg.plotW, plotH=cfg.plotH;
      var axisMax=cfg.axisMax, tickStep=cfg.tickStep;
