        s += '<text x="'+(plotX-6)+'" y="'+(y+6)+'" font-size="18" fill="#333" text-anchor="end">'+v+'</text>';
      }
      var n=cfg.values.length;
      var groupW=plotW/n;
      var barWidth=Math.min(cfg.barWidth||80, groupW*0.6);
      for (var i=0; i<n; i++) {
        var val=cfg.values[i];
        var x = plotX + i*groupW + (groupW-barWidth)/2;
        var h = (val/axisMax)*plotH;
        var y = plotY + plotH - h;
        s += '<rect x="'+x+'" y="'+y+'" width="'+barWidth+'" height="'+h+'" fill="'+(cfg.barColor||'#4a90e2')+'"/>';
        s += '<text x="'+(x+barWidth/2)+'" y="'+(y-8)+'" font-size="18" fill="#111" text-anchor="middle">'+val+'</text>';
        s += '<text x="'+(plotX + i*groupW + groupW/2)+'" y="'+(plotY+plotH+20)+'" font-size="18" fill="#333" text-anchor="middle">'+cfg.xLabels[i]+'</text>';
      }
      s += '<text x="20" y="'+(plotY+plotH/2)+'" transform="rotate(-90 20 '+(plotY+plotH/2)+')" font-size="18" fill="#333">'+cfg.yTitle+'</text>';
      s += '<text x="'+(plotX+plotW/2)+'" y="'+(plotY+plotH+40)+'" font-size="18" fill="#333" text-anchor="middle">'+cfg.xTitle+'</text>';
    }
    svg.innerHTML = s;
  }

