      var axisMax=cfg.axisMax, tickStep=cfg.tickStep;
      var barHeight=cfg.barHeight||52, barGap=cfg.barGap||70;
      s += '<line x1="'+plotX+'" y1="'+(plotY-10)+'" x2="'+plotX+'" y2="'+(plotY+plotH+10)+'" stroke="#999" stroke-width="1"/>';
      s += '<line x1="'+plotX+'" y1="'+(plotY+plotH+10)+'" x2="'+(plotX+plotW)+'" y2="'+(plotY+plotH+10)+'" stroke="#999" stroke-width="1"/>';
      for (var v=0; v<=axisMax; v+=tickStep) {
        var x = plotX + (v/axisMax)*plotW;
        s += '<line x1="'+x+'" y1="'+(plotY-10)+'" x2="'+x+'" y2="'+(plotY+plotH+10)+'" stroke="#ccc" stroke-width="1"/>';
        s += '<text x="'+x+'" y="'+(plotY+plotH+30)+'" font-size="18" fill="#333" text-anchor="middle">'+v+'</text>';
      }
      for (var i=0; i<cfg.values.length; i++) {
        var val=cfg.values[i];
